"""ES5.6 scroll -> private SQLite archive -> typeless ES9 bulk. All differences block cutover."""
import copy
import datetime
import hashlib
import itertools
import os
import re
from pathlib import Path
import sqlite3
import time
from common import Blocked, HTTP, HTTPFailure, atomic, canonical, complete, decode, digest, free_space, segment
from control import Control, hash_file


CATALOGUE = ['account', 'event', 'machine', 'project', 'subscription', 'training', 'user', 'space', 'order', 'availabilities']


def target_internal(index):
    # Generated by this fresh ES9 cluster, never copied from the source or deleted.
    return index in ('.security-7', '.security-tokens-7') or bool(re.fullmatch(
        r'\.ds-(?:\.logs-elasticsearch\.deprecation-default|ilm-history-7)-\d{4}\.\d{2}\.\d{2}-\d{6}', index))


class Transfer:
    def __init__(self, ledger):
        self.journal, self.config = ledger, ledger.config
        self.control = Control(ledger)
        self.schema = decode(Path(self.config['schema_file']).read_text())
        if sorted(self.schema['families']) != sorted(CATALOGUE) or self.schema['format'] != 1:
            raise Blocked('Expected the reviewed ten-family schema artifact')
        if digest(self.schema) != self.config['schema_sha256']:
            raise Blocked('Schema artifact changed')
        self.families = self.schema['families']
        datetime.date.fromisoformat(self.config['protected_through'])
        for family, spec in self.families.items():
            expected_alias = 'fm-availabilities' if family == 'availabilities' else 'fm-stats-' + family
            if spec['source_type'] != family or spec['source_index'] != ('fablab' if family == 'availabilities' else 'stats'):
                raise Blocked('Unreviewed source catalogue')
            if spec['target'] != expected_alias + '-v1' or spec['alias'] != expected_alias:
                raise Blocked('Unreviewed destination identity mapping')
        for key, low, high in [('page_size', 1, 1000), ('bulk_bytes', 1024, 16 * 1024 * 1024),
                               ('document_bytes', 128, 8 * 1024 * 1024)]:
            if not low <= self.config[key] <= high:
                raise Blocked('Invalid memory bound: ' + key)

    def clients(self):
        self.control.topology(attach=True)
        self.source = HTTP(self.config['source'], self.control.address('source'))
        self.target = HTTP(self.config['target'], self.control.address('target'))
        infos = {}
        for side in ('source', 'target'):
            info = getattr(self, side).request('GET', '/')
            if info['version']['number'] != self.config[side]['version']:
                raise Blocked('Unexpected exact ' + side + ' server version')
            infos[side] = info['cluster_uuid']
            if len(getattr(self, side).request('GET', '/_nodes')['nodes']) != 1:
                raise Blocked('This control adapter supports one node per cluster')
        if infos['source'] == infos['target']:
            raise Blocked('Source and target must be different clusters')
        if self.journal.state.get('clusters', infos) != infos:
            raise Blocked('Cluster identity changed')
        self.journal.save(clusters=infos)

    def inspect_source(self):
        metadata = self.source.request('GET', '/_cluster/state/metadata')['metadata']
        nodes = self.source.request('GET', '/_nodes/plugins')['nodes']
        node_paths = self.source.request('GET', '/_nodes/settings?filter_path=nodes.*.settings.path')['nodes']
        stats = self.source.request('GET', '/_stats/docs,store')['indices']
        mappings = self.source.request('GET', '/_mapping?expand_wildcards=all')
        settings = self.source.request('GET', '/_settings?expand_wildcards=all')
        aliases = self.source.request('GET', '/_aliases?expand_wildcards=all')
        file_scripts = self.control.run('exec', self.config['docker']['source'], 'sh', '-c',
            'if test -d /usr/share/elasticsearch/config/scripts; then find /usr/share/elasticsearch/config/scripts -type f -print; fi').decode().splitlines()
        result = {'metadata': metadata, 'nodes': nodes, 'settings': settings, 'mappings': mappings,
                  'node_paths': node_paths, 'aliases': aliases, 'stats': stats, 'file_scripts': file_scripts, 'families': {}, 'blockers': []}
        blocks = result['blockers']
        for node in node_paths.values():
            paths = node['settings']['path']
            if paths.get('home') != '/usr/share/elasticsearch' or paths.get('conf', '/usr/share/elasticsearch/config') != '/usr/share/elasticsearch/config' or paths.get('scripts', '/usr/share/elasticsearch/config/scripts') != '/usr/share/elasticsearch/config/scripts':
                blocks.append('Nonstandard source script/config path requires an explicit inventory adapter')
        environment = dict(line.split('=', 1) for line in self.control.inspect(self.config['docker']['source'])['Config']['Env'] if '=' in line)
        if any(environment.get(key, '/usr/share/elasticsearch/config') != '/usr/share/elasticsearch/config' for key in ('ES_PATH_CONF', 'CONF_DIR')):
            blocks.append('Nonstandard source configuration environment requires explicit script inventory')
        if set(mappings) - {'stats', 'fablab'}:
            blocks.append('Unknown source indices (including system/plugin indices): ' + ', '.join(sorted(set(mappings) - {'stats', 'fablab'})))
        if file_scripts:
            blocks.append('File scripts require a separate explicit migration')
        if metadata.get('templates') or metadata.get('ingest', {}).get('pipeline'):
            blocks.append('Source templates/pipelines require an explicit migration')
        if any('script' in key.lower() and value for key, value in metadata.items()):
            blocks.append('Stored scripts require explicit migration')
        for node in nodes.values():
            if node.get('plugins'):
                blocks.append('Installed plugins require explicit migration: ' + ', '.join(item['name'] for item in node['plugins']))
        for index, detail in aliases.items():
            if detail.get('aliases'):
                blocks.append('Source aliases require explicit migration: ' + index)
        for index, detail in mappings.items():
            if settings[index]['settings']['index'].get('analysis') or detail['mappings'].get('_default_'):
                blocks.append('Custom index analysis/default mappings require explicit treatment: ' + index)
            for kind, mapping in detail['mappings'].items():
                if kind == '_default_':
                    continue
                family = kind if kind in self.families and self.families[kind]['source_index'] == index else None
                if not family:
                    blocks.append('Unknown source family: ' + index + '/' + kind)
                count_result = self.source.request('GET', '/' + segment(index) + '/' + segment(kind) + '/_count')
                complete(count_result)
                entry = {'count': count_result['count'], 'missing_source': 0, 'routed': 0, 'reserved_metadata': 0}
                for page in self.source.scroll('/' + segment(index) + '/' + segment(kind) + '/_search', page_size=self.config['page_size']):
                    for hit in page:
                        entry['missing_source'] += not isinstance(hit.get('_source'), dict)
                        entry['routed'] += bool(hit.get('_routing') or hit.get('_parent') or hit.get('fields', {}).get('_routing'))
                        entry['reserved_metadata'] += '__fm' in (hit.get('_source') or {})
                result['families'][index + '/' + kind] = entry
                source = mapping.get('_source', {})
                if source.get('enabled') is False or source.get('includes') or source.get('excludes') or entry['missing_source']:
                    blocks.append('Unavailable or filtered _source: ' + index + '/' + kind)
                if mapping.get('_parent') or mapping.get('_routing', {}).get('required') or entry['routed']:
                    blocks.append('Custom routing/parent requires explicit update/delete contract: ' + index + '/' + kind)
                if entry['reserved_metadata']:
                    blocks.append('Reserved __fm collision: ' + index + '/' + kind)
                if mapping.get('dynamic_templates'):
                    blocks.append('Custom dynamic templates require explicit treatment: ' + index + '/' + kind)
                if family:
                    try:
                        self.definition(family, mapping)
                    except Blocked as error:
                        blocks.append(str(error))
        return result

    def inventory(self):
        self.journal.require('new', 'inventoried')
        self.clients()
        result = self.inspect_source()
        # SQL-held aggregation templates are also scripts/queries, not just ES cluster metadata.
        sql_queries = self.sql_queries()
        if sql_queries != self.schema['sql_custom_aggregations']:
            result['blockers'].append('SQL custom queries differ from the reviewed schema/probe artifact')
        result['sql_custom_aggregations'] = sql_queries
        atomic(self.journal.root / 'inventory.json', result)
        self.journal.save(phase='inventoried', inventory_sha256=digest(result), blockers=result['blockers'])
        if result['blockers']:
            raise Blocked('; '.join(result['blockers']))
        self.journal.event('inventory_complete', counts={key: value['count'] for key, value in result['families'].items()})

    def sql_queries(self):
        raw = self.control.sql('SELECT row_to_json(q) FROM (SELECT id, es_index, es_type, field, query FROM statistic_custom_aggregations ORDER BY id) q')
        return [decode(line) for line in raw.decode().splitlines()]

    def check_sql(self):
        if self.sql_queries() != self.schema['sql_custom_aggregations']:
            raise Blocked('SQL custom queries changed before the coherent snapshot')

    def maintenance(self):
        self.journal.require('inventoried', 'maintenance_start')
        if self.journal.state.get('blockers'):
            raise Blocked('Inventory blockers are unresolved')
        self.clients()
        self.control.capture_activation()
        self.journal.save(phase='maintenance_start')
        self.journal.runtime()
        self.control.stop_producers(self.check_sql)
        indices = self.source.request('GET', '/_settings')
        if set(indices) - {'stats', 'fablab'}:
            raise Blocked('An unknown index appeared before the final copy')
        original = {index: data['settings']['index'].get('blocks', {}).get('write') for index, data in indices.items()}
        self.journal.save(original_write_blocks=self.journal.state.get('original_write_blocks', original))
        for index in indices:
            self.source.request('PUT', '/' + segment(index) + '/_settings', {'index.blocks.write': True})
        self.source.request('POST', '/_flush?wait_if_ongoing=true')
        self.source.request('POST', '/_refresh')
        self.tasks()
        frozen = self.inspect_source()
        atomic(self.journal.root / 'frozen-inventory.json', frozen)
        if frozen['blockers']:
            raise Blocked('; '.join(frozen['blockers']))
        self.journal.save(phase='maintenance', frozen_sha256=digest(frozen), frozen_at=time.time())
        self.journal.runtime()
        self.journal.event('maintenance_established', pending=self.journal.state['pending'])

    def tasks(self):
        result = self.source.request('GET', '/_tasks?detailed=true')
        atomic(self.journal.root / 'source-tasks.json', result)
        for node in result.get('nodes', {}).values():
            for task in node.get('tasks', {}).values():
                if not task['action'].startswith(('cluster:monitor/', 'indices:monitor/', 'indices:data/read/')):
                    raise Blocked('Source task still active: ' + task['action'])

    def frozen(self):
        self.clients()
        self.control.stopped()
        settings = self.source.request('GET', '/_settings?expand_wildcards=all')
        inventory = decode((self.journal.root / 'frozen-inventory.json').read_text())
        if digest(inventory) != self.journal.state['frozen_sha256']:
            raise Blocked('Frozen inventory artifact changed')
        if set(settings) != set(inventory['settings']):
            raise Blocked('Source index set changed')
        for index, detail in settings.items():
            current = detail['settings']['index']
            expected = inventory['settings'][index]['settings']['index']
            if current.get('blocks', {}).get('write') != 'true' or current.get('uuid') != expected.get('uuid'):
                raise Blocked('Source write fence or index identity changed')
        if settings != inventory['settings']:
            raise Blocked('Source settings changed')
        for name, path in [('mappings', '/_mapping?expand_wildcards=all'), ('aliases', '/_aliases?expand_wildcards=all')]:
            if self.source.request('GET', path) != inventory[name]:
                raise Blocked('Source ' + name + ' changed')
        metadata = self.source.request('GET', '/_cluster/state/metadata')['metadata']
        if self.source.request('GET', '/_nodes/settings?filter_path=nodes.*.settings.path')['nodes'] != inventory['node_paths']:
            raise Blocked('Source node paths changed')
        if any(metadata.get(key) != inventory['metadata'].get(key) for key in ('templates', 'ingest')):
            raise Blocked('Source templates/pipelines changed')
        if any('script' in key.lower() and value for key, value in metadata.items()):
            raise Blocked('Source scripts appeared during maintenance')
        if any(node.get('plugins') for node in self.source.request('GET', '/_nodes/plugins')['nodes'].values()):
            raise Blocked('Source plugins changed')
        scripts = self.control.run('exec', self.config['docker']['source'], 'sh', '-c',
            'if test -d /usr/share/elasticsearch/config/scripts; then find /usr/share/elasticsearch/config/scripts -type f -print; fi').decode().splitlines()
        if scripts != inventory['file_scripts']:
            raise Blocked('Source file scripts changed')
        self.tasks()
        return inventory

    def backup(self):
        self.journal.require('maintenance', 'backed_up')
        self.frozen()
        free_space(self.journal.root, self.config['minimum_free_bytes'])
        self.snapshot()
        self.control.backups()
        self.journal.save(phase='backed_up')
        self.journal.event('compatible_backups_complete')

    def snapshot(self):
        options = self.config['snapshot']
        repository = segment(options['repository'])
        volume = self.control.volume('source_backup')
        if volume in {self.control.volume(side) for side in ('source', 'target', 'sql', 'redis')}:
            raise Blocked('Snapshot repository requires a separate dedicated volume')
        expected = {'type': 'fs', 'settings': {'location': options['location'], 'compress': True}}
        try:
            actual = self.source.request('GET', '/_snapshot/' + repository)[options['repository']]
            if actual['type'] != 'fs' or actual['settings'].get('location') != options['location'] or actual['settings'].get('readonly') == 'true':
                raise Blocked('Existing snapshot repository does not match the explicit private path')
        except HTTPFailure as error:
            if error.status != 404:
                raise
            self.source.request('PUT', '/_snapshot/' + repository, expected)
        self.source.request('POST', '/_snapshot/' + repository + '/_verify')
        name = 'fm-' + self.journal.state['run_id']
        path = '/_snapshot/' + repository + '/' + name
        try:
            info = self.source.request('GET', path)['snapshots'][0]
        except HTTPFailure as error:
            if error.status != 404:
                raise
            indices = sorted(decode((self.journal.root / 'frozen-inventory.json').read_text())['mappings'])
            # Completion is polled in a later invocation if the host or connection is interrupted.
            self.source.request('PUT', path, {'indices': ','.join(indices), 'include_global_state': True, 'partial': False})
            info = self.source.request('GET', path)['snapshots'][0]
        for _ in range(60):
            if info['state'] != 'IN_PROGRESS':
                break
            time.sleep(1)
            info = self.source.request('GET', path)['snapshots'][0]
        if info['state'] != 'SUCCESS' or info.get('failures') or info['shards']['failed'] or info['shards']['successful'] != info['shards']['total']:
            raise Blocked('Native ES5 snapshot is incomplete or failed; retry backup to inspect it')
        current = self.source.request('GET', '/_snapshot/' + repository + '/_current')['snapshots']
        if current:
            raise Blocked('Another snapshot is active; do not archive a changing repository')
        self.journal.save(snapshot={'repository': options['repository'], 'name': name, 'result': info})

    def definition(self, family, legacy):
        result = copy.deepcopy(self.families[family]['definition'])
        target = result['mappings']['properties']
        merge_properties(target, legacy.get('properties', {}))
        result['mappings']['_meta']['fm_migration_run'] = self.journal.state['run_id']
        return result

    def export(self):
        self.journal.require('backed_up', 'exporting', 'exported')
        inventory = self.frozen()
        self.journal.save(phase='exporting')
        for family, spec in self.families.items():
            entry = inventory['families'].get(spec['source_index'] + '/' + family)
            if not entry:
                continue  # Absent known families are created empty, never inferred as deleted histories.
            scan = 'export-' + family
            self.journal.db.execute('DELETE FROM observations WHERE side=?', (scan,))
            self.journal.db.commit()
            path = '/' + segment(spec['source_index']) + '/' + segment(family) + '/_search'
            for hits in self.source.scroll(path, page_size=self.config['page_size']):
                free_space(self.journal.root, self.config['minimum_free_bytes'] + self.config['bulk_bytes'] * 4)
                with self.journal.db:
                    for hit in hits:
                        if hit['_index'] != spec['source_index'] or hit['_type'] != family:
                            raise Blocked('Unexpected source document identity')
                        content = canonical(hit['_source'])
                        if '__fm' in hit['_source'] or len(content.encode()) > self.config['document_bytes']:
                            raise Blocked('Reserved metadata or oversized document: ' + hit['_id'])
                        identity = (spec['source_index'], family, hit['_id'])
                        sha = digest(hit['_source'])
                        floor = protected_floor(self.journal.state.get('protected_through', self.config['protected_through']), family, hit['_source'])
                        if self.journal.state.get('protected_through') != floor:
                            self.journal.save(protected_through=floor)
                        previous = self.journal.db.execute('SELECT sha256 FROM documents WHERE source_index=? AND source_type=? AND id=?', identity).fetchone()
                        if previous and previous[0] != sha:
                            raise Blocked('Source content changed during resumed export: ' + canonical(identity))
                        self.journal.db.execute('INSERT OR IGNORE INTO documents(source_index,source_type,id,target_index,content,sha256) VALUES(?,?,?,?,?,?)',
                                                (*identity, spec['target'], content, sha))
                        self.observe(scan, spec['target'], hit['_id'], sha)
            seen = self.journal.db.execute('SELECT count(*) FROM observations WHERE side=?', (scan,)).fetchone()[0]
            stored = self.journal.db.execute('SELECT count(*) FROM documents WHERE source_type=?', (family,)).fetchone()[0]
            if seen != entry['count'] or stored != seen:
                raise Blocked('Identity count changed or incomplete export: ' + family)
            self.journal.event('family_exported', family=family, count=seen)
        self.journal.save(phase='exported')

    def initialize(self):
        self.journal.require('exported', 'initialized')
        inventory = self.frozen()
        indices = self.target.request('GET', '/_mapping?expand_wildcards=all')
        self.check_aliases()
        allowed = {spec['target'] for spec in self.families.values()} | {'.security-7', '.security-tokens-7'}
        if any(index not in allowed and not target_internal(index) for index in indices):
            raise Blocked('Target contains an unreviewed index')
        # Validate every existing target before creating any new index.
        definitions = {}
        for family, spec in self.families.items():
            legacy = inventory['mappings'].get(spec['source_index'], {}).get('mappings', {}).get(family, {})
            definition = self.definition(family, legacy)
            definitions[family] = definition
            if spec['target'] in indices:
                actual = indices[spec['target']]['mappings']
                if not contains(actual, definition['mappings']):
                    raise Blocked('Target mapping incompatible or belongs to another migration: ' + spec['target'])
        for family, spec in self.families.items():
            if spec['target'] not in indices:
                self.target.request('PUT', '/' + spec['target'], definitions[family])
        atomic(self.journal.root / 'target-definitions.json', definitions)
        self.journal.save(phase='initialized')

    def import_data(self):
        self.journal.require('initialized', 'importing', 'imported')
        self.frozen()
        self.check_target()
        self.journal.save(phase='importing')
        while True:
            rows = self.journal.db.execute('SELECT source_type,id,target_index,content FROM documents WHERE imported=0 ORDER BY target_index,id LIMIT ?',
                                          (self.config['page_size'],))
            first = rows.fetchone()
            if first is None:
                break
            batch, payload = [], b''
            for family, identity, index, content in itertools.chain([first], rows):
                source = decode(content)
                source['__fm'] = {'uid': family + '#' + identity}
                encoded = (canonical({'index': {'_index': index, '_id': identity}}) + '\n' + canonical(source) + '\n').encode()
                if len(encoded) > self.config['bulk_bytes']:
                    raise Blocked('Single document exceeds bulk byte bound')
                if len(payload) + len(encoded) > self.config['bulk_bytes']:
                    break
                payload += encoded
                batch.append((family, identity, index))
            rows.close()
            fs = self.target.request('GET', '/_nodes/stats/fs')['nodes']
            if any(node['fs']['total']['available_in_bytes'] < self.config['minimum_free_bytes'] + len(payload) * 4 for node in fs.values()):
                raise Blocked('Insufficient target disk capacity')
            response = self.target.request('POST', '/_bulk', payload, raw=True)
            items = response.get('items', [])
            if len(items) != len(batch):
                raise Blocked('Bulk response item count mismatch; unacknowledged IDs remain resumable')
            failures = []
            with self.journal.db:
                for (family, identity, index), item in zip(batch, items):
                    result = item.get('index', {})
                    if result.get('_id') != identity or result.get('_index') != index:
                        raise Blocked('Bulk acknowledgement identity mismatch')
                    if 200 <= result.get('status', 0) < 300 and not result.get('error'):
                        self.journal.db.execute('UPDATE documents SET imported=1 WHERE source_type=? AND id=?', (family, identity))
                    else:
                        failures.append({'family': family, 'id': identity, 'status': result.get('status'), 'error': result.get('error')})
            self.journal.event('bulk_result', attempted=len(batch), succeeded=len(batch)-len(failures), failures=failures)
            if failures or response.get('errors'):
                raise Blocked('Bulk failed for individual documents; no item was skipped')
        self.journal.save(phase='imported')

    def observe(self, side, index, identity, sha):
        previous = self.journal.db.execute('SELECT sha256 FROM observations WHERE side=? AND target_index=? AND id=?', (side, index, identity)).fetchone()
        if previous and previous[0] != sha:
            raise Blocked('Document changed while scanning: ' + identity)
        self.journal.db.execute('INSERT OR IGNORE INTO observations VALUES(?,?,?,?)', (side, index, identity, sha))

    def validation(self):
        self.journal.require('imported', 'validated', 'switched')
        inventory = self.frozen()
        self.control.verify_backups()
        self.check_target()
        self.journal.db.execute("DELETE FROM observations WHERE side IN ('source','target')")
        self.journal.db.commit()
        self.target.request('POST', '/_refresh')
        result = {'families': {}, 'differences': [], 'probes': {}}
        for family, spec in self.families.items():
            index, kind, target = spec['source_index'], spec['source_type'], spec['target']
            source_present = index + '/' + kind in inventory['families']
            sources = [('target', self.target, '/' + target + '/_search?track_total_hits=true')]
            if source_present:
                sources.append(('source', self.source, '/' + segment(index) + '/' + segment(kind) + '/_search'))
            for side, client, path in sources:
                for hits in client.scroll(path, page_size=self.config['page_size']):
                    with self.journal.db:
                        for hit in hits:
                            content = hit.get('_source')
                            if not isinstance(content, dict):
                                raise Blocked('Missing _source during validation')
                            if side == 'target':
                                if content.pop('__fm', None) != {'uid': family + '#' + hit['_id']}:
                                    raise Blocked('Identity metadata mismatch')
                            self.observe(side, target, hit['_id'], digest(content))
            expected_count = self.journal.db.execute('SELECT count(*) FROM documents WHERE target_index=?', (target,)).fetchone()[0]
            for side in ('source', 'target'):
                count = self.journal.db.execute('SELECT count(*) FROM observations WHERE side=? AND target_index=?', (side, target)).fetchone()[0]
                missing = self.journal.db.execute('''SELECT d.id FROM documents d LEFT JOIN observations o ON
                    o.side=? AND o.target_index=d.target_index AND o.id=d.id WHERE d.target_index=? AND (o.sha256 IS NULL OR o.sha256<>d.sha256)''', (side, target)).fetchmany(100)
                extra = self.journal.db.execute('''SELECT o.id FROM observations o LEFT JOIN documents d ON d.target_index=o.target_index AND d.id=o.id
                    WHERE o.side=? AND o.target_index=? AND d.id IS NULL''', (side, target)).fetchmany(100)
                if count != expected_count or missing or extra:
                    result['differences'].append({'family': family, 'side': side, 'expected': expected_count, 'actual': count,
                                                   'missing_or_changed_examples': [x[0] for x in missing], 'extra_examples': [x[0] for x in extra]})
                result['families'].setdefault(family, {})[side] = {'count': count, 'identities_and_contents_sha256': self.fingerprint(side, target)}
            if source_present:
                result['probes'][family] = []
                for probe in spec['probes']:
                    before = self.source.request('POST', '/' + segment(index) + '/' + segment(kind) + '/_search', probe['source'])
                    after = self.target.request('POST', '/' + target + '/_search', probe['target'])
                    complete(before)
                    complete(after)
                    equal = before.get('aggregations') == after.get('aggregations')
                    result['probes'][family].append({'name': probe['name'], 'equal': equal,
                        'source': before.get('aggregations'), 'target': after.get('aggregations')})
                    if not equal:
                        result['differences'].append({'family': family, 'probe': probe['name']})
        result['ok'] = not result['differences']
        atomic(self.journal.root / 'comparison.json', result)
        if not result['ok']:
            raise Blocked('Counts, complete identities, contents or business aggregations differ; see comparison.json')
        for spec in self.families.values():
            self.target.request('PUT', '/' + spec['target'] + '/_settings', {'index.blocks.write': True})
        self.journal.save(phase='validated', validation_sha256=digest(result))
        self.journal.runtime(target_cluster_uuid=self.journal.state['clusters']['target'])
        self.journal.event('validated', result_sha256=digest(result))
        return result

    def fingerprint(self, side, index):
        result = hashlib.sha256()
        for row in self.journal.db.execute('SELECT id,sha256 FROM observations WHERE side=? AND target_index=? ORDER BY id', (side, index)):
            result.update((canonical(list(row)) + '\n').encode())
        return result.hexdigest()

    def switch(self):
        self.journal.require('validated', 'switched')
        self.validation()  # Never promote an old comparison after source/target drift.
        actions = []
        for family, spec in self.families.items():
            actions.append({'add': {'index': spec['target'], 'alias': spec['alias'], 'is_write_index': True}})
            if family != 'availabilities':
                actions.append({'add': {'index': spec['target'], 'alias': 'fm-stats-all'}})
        self.target.request('POST', '/_aliases', {'actions': actions})
        self.control.activation(True)
        self.journal.save(phase='switched')
        self.journal.runtime(target_cluster_uuid=self.journal.state['clusters']['target'])
        self.journal.event('activation_switched_writes_closed')

    def rollback(self):
        self.journal.require('maintenance_start', 'maintenance', 'backed_up', 'exporting', 'exported', 'initialized', 'importing', 'imported', 'validated', 'switched')
        if self.journal.state['phase'] == 'maintenance_start':
            self.clients()
            self.control.stopped()
        else:
            self.frozen()
        self.control.activation(False)
        for index, original in self.journal.state.get('original_write_blocks', {}).items():
            self.source.request('PUT', '/' + segment(index) + '/_settings', {'index.blocks.write': original})
        self.journal.save(phase='rolled_back')
        self.journal.runtime()
        self.journal.event('rollback_before_writes', pending_preserved=True)

    def reopen(self):
        self.journal.require('switched', 'writes_open')
        self.control.verify_deployment()
        if not self.journal.state.get('target_producers_reviewed'):
            raise Blocked('Run adopt-producers after staging the reviewed target deployment')
        if self.journal.state['phase'] == 'switched':
            self.validation()
            # Mark the point of no silent return BEFORE unlocking even one index or SQL/Redis.
            self.journal.save(phase='writes_open', reopened_at=time.time())
        else:
            self.clients()
            self.check_target()
            if any(self.control.inspect(item['name'])['State']['Running'] for item in self.config['docker']['producers']):
                raise Blocked('Stop producers before completing an interrupted reopen')
        for spec in self.families.values():
            self.target.request('PUT', '/' + spec['target'] + '/_settings', {'index.blocks.write': False})
        self.journal.runtime(target_cluster_uuid=self.journal.state['clusters']['target'], reopened_at=self.journal.state['reopened_at'])
        self.control.run('start', self.config['docker']['sql'], self.config['docker']['redis'])
        self.journal.event('writes_open_no_automatic_producer_start', legacy_queues_held=True)

    def adopt_producers(self):
        self.journal.require('switched')
        self.control.verify_deployment()
        self.control.topology(attach=True, adopt=True)
        self.journal.save(target_producers_reviewed=True)
        self.journal.event('stopped_target_producers_adopted')

    def adopt_target(self):
        self.journal.require('writes_open')
        if any(self.control.inspect(item['name'])['State']['Running'] for item in self.config['docker']['producers']):
            raise Blocked('Stop all producers before adopting a recreated target')
        client = HTTP(self.config['target'], self.control.address('target'))
        info = client.request('GET', '/')
        if info['cluster_uuid'] != self.journal.state['clusters']['target'] or info['version']['number'] != self.config['target']['version']:
            raise Blocked('Recreated target must retain its original cluster UUID and exact reviewed version')
        self.control.topology(attach=True, adopt_target=True)
        self.target = client
        self.check_target()
        self.journal.event('recreated_target_adopted_after_uuid_volume_image_schema_verification')

    def audit_target(self):
        self.journal.require('writes_open')
        self.control.topology(attach=True)
        client = HTTP(self.config['target'], self.control.address('target'))
        if client.request('GET', '/')['cluster_uuid'] != self.journal.state['clusters']['target']:
            raise Blocked('Wrong target cluster for reconciliation')
        self.journal.db.execute("DELETE FROM observations WHERE side='audit'")
        self.journal.db.commit()
        for family, spec in self.families.items():
            for hits in client.scroll('/' + spec['target'] + '/_search?track_total_hits=true', page_size=self.config['page_size']):
                with self.journal.db:
                    for hit in hits:
                        content = hit['_source']
                        if content.pop('__fm', None) != {'uid': family + '#' + hit['_id']}:
                            raise Blocked('Reconciliation identity metadata mismatch')
                        self.observe('audit', spec['target'], hit['_id'], digest(content))
        counts = {'new': 0, 'changed': 0, 'deleted': 0}
        path = self.journal.root / ('reconciliation-' + str(time.time_ns()) + '.jsonl')
        with path.open('x') as stream:
            os.chmod(path, 0o600)
            queries = {
                'new': "SELECT o.target_index,o.id,NULL,o.sha256 FROM observations o LEFT JOIN documents d ON d.target_index=o.target_index AND d.id=o.id WHERE o.side='audit' AND d.id IS NULL",
                'changed': "SELECT d.target_index,d.id,d.sha256,o.sha256 FROM documents d JOIN observations o ON o.target_index=d.target_index AND o.id=d.id AND o.side='audit' WHERE d.sha256<>o.sha256",
                'deleted': "SELECT d.target_index,d.id,d.sha256,NULL FROM documents d LEFT JOIN observations o ON o.target_index=d.target_index AND o.id=d.id AND o.side='audit' WHERE o.id IS NULL"}
            for kind, query in queries.items():
                for index, identity, before, after in self.journal.db.execute(query):
                    counts[kind] += 1
                    stream.write(canonical({'kind': kind, 'index': index, 'id': identity, 'before': before, 'after': after}) + '\n')
        self.journal.event('reconciliation_audit', counts=counts, path=str(path), sha256=hash_file(path),
                           limitation='Per-index point-in-time reads only; stop all producers for a coherent reconciliation. SQL/jobs/external effects need separate review.')
        return counts

    def check_aliases(self):
        allowed = {spec['target']: {spec['alias']: {'is_write_index': True},
                   **({'fm-stats-all': {}} if family != 'availabilities' else {})}
                   for family, spec in self.families.items()}
        actual = self.target.request('GET', '/_aliases?expand_wildcards=all')
        if self.journal.state['phase'] in ('switched', 'writes_open'):
            if any(actual.get(index, {}).get('aliases') != definitions for index, definitions in allowed.items()):
                raise Blocked('Required target aliases changed after switch')
        for index, detail in actual.items():
            if target_internal(index):
                continue
            for name, definition in detail.get('aliases', {}).items():
                if name not in allowed.get(index, {}) or definition != allowed[index][name]:
                    raise Blocked('Unreviewed target alias or alias options')

    def check_target(self):
        self.check_aliases()
        definitions = decode((self.journal.root / 'target-definitions.json').read_text())
        mappings = self.target.request('GET', '/_mapping?expand_wildcards=all')
        for family, spec in self.families.items():
            if not contains(mappings.get(spec['target'], {}).get('mappings'), definitions[family]['mappings']):
                raise Blocked('Target mapping changed')
        if any(index not in {spec['target'] for spec in self.families.values()} and not target_internal(index) for index in mappings):
            raise Blocked('Unreviewed target index appeared')


def protected_floor(current, family, source):
    """Imported statistics are protected through their latest date. Availability dates are
    schedules, often in the future: they must not stop the daily statistics after cutover."""
    date = source.get('date')
    if family == 'availabilities' or date is None:
        return current
    try:
        day = datetime.date.fromisoformat(str(date)[:10]).isoformat()
    except ValueError:
        day = '9999-12-31'  # Unknown date representation never permits an automatic historical rebuild.
    return max(current, day)


def contains(actual, expected):
    if not isinstance(expected, dict):
        return actual == expected
    return isinstance(actual, dict) and all(key in actual and contains(actual[key], value) for key, value in expected.items())


def merge_properties(target, legacy):
    for key, value in legacy.items():
        converted = convert_mapping(value)
        if key not in target:
            target[key] = converted
        elif target[key].get('type') in ('float', 'double'):
            # Historical numeric precision is an indexing contract, even when _source is identical.
            if converted.get('type') not in ('float', 'double', 'long', 'integer', 'short', 'byte'):
                raise Blocked('Numeric field requires explicit precision treatment: ' + key)
            target[key] = converted
        elif 'properties' in converted:
            merge_properties(target[key].setdefault('properties', {}), value['properties'])


def convert_mapping(value):
    result = copy.deepcopy(value)
    kind = result.get('type', 'object' if 'properties' in result else None)
    if kind not in ('string', 'text', 'keyword', 'date', 'long', 'integer', 'short', 'byte', 'float', 'double', 'boolean', 'object', 'scaled_float'):
        raise Blocked('Unsupported historical mapping type: ' + str(kind))
    if result.get('analyzer', 'standard') not in ('standard', 'simple', 'keyword', 'whitespace', 'stop'):
        raise Blocked('Custom analyzer requires an explicit migration')
    if kind == 'string':
        result['type'] = 'keyword' if result.get('index') == 'not_analyzed' else 'text'
    if result.get('index') in ('analyzed', 'not_analyzed'):
        result.pop('index')
    elif result.get('index') == 'no':
        result['index'] = False
    result.pop('include_in_all', None)
    for key in ('properties', 'fields'):
        if key in result:
            result[key] = {name: convert_mapping(detail) for name, detail in result[key].items()}
    return result
